import os,pty,fcntl,termios,subprocess,tempfile,signal,time,select
exe=os.path.abspath('./executable')
with tempfile.TemporaryDirectory(prefix='entr-tty-') as d:
 f=d+'/a';open(f,'w').write('A')
 def run(flags,cmd,pipein=True,terminal=True,actions=[(0.2,b' '),(0.2,b'q')]):
  master,slave=pty.openpty()
  def prepare():
   os.setsid()
   if terminal:fcntl.ioctl(slave,termios.TIOCSCTTY,0)
  p=subprocess.Popen([exe]+flags+cmd,stdin=subprocess.PIPE if pipein else slave,stdout=slave,stderr=slave,preexec_fn=prepare,pass_fds=(slave,))
  if pipein:p.stdin.write((f+'\n').encode());p.stdin.close()
  os.close(slave);output=b''
  def read(n):
   nonlocal output
   end=time.monotonic()+n
   while time.monotonic()<end:
    if select.select([master],[],[],max(0,end-time.monotonic()))[0]:
     try:b=os.read(master,65536)
     except OSError:return
     if not b:return
     output+=b
  for delay,data in actions:
   read(delay)
   if p.poll() is None:os.write(master,data)
  read(.3)
  if p.poll() is None:p.send_signal(signal.SIGINT)
  read(.2)
  if p.poll() is None:os.killpg(p.pid,signal.SIGKILL)
  read(.1)
  rc=p.wait();os.close(master)
  print(flags,cmd,'pipein',pipein,'terminal',terminal,rc,repr(output.replace(d.encode(),b'TMP')))
