set -eu
cd "$(dirname "$0")"
# The implementation uses only the C library and Linux kernel interfaces.
# A standard C compiler is sufficient; there are no third-party dependencies.
${CC:-cc} -std=c11 -O2 -Wall -Wextra -Wpedantic src/main.c -o executable
EOF
chmod +x compile.sh
cat > src/main.c <<'EOF'
#define _GNU_SOURCE
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/inotify.h>
#include <sys/wait.h>
#include <sys/resource.h>
#include <fcntl.h>
#include <unistd.h>
#include <poll.h>
#include <signal.h>
#include <termios.h>
#include <dirent.h>
#include <pwd.h>
#include <errno.h>
#include <limits.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

/* A file-event runner.  The watch list, process runner and input controller are
 * intentionally independent: events are folded into a batch before deciding
 * whether a new invocation is needed. */

static const char *program;
static int opt_all, opt_clear, opt_directory, opt_noninteractive;
static int opt_postpone, opt_restart, opt_shell, opt_status, opt_exit;
static int trace_events, follow_links, workaround, restart_signal = SIGTERM;
static int notify_fd = -1, tty_fd = -1, status_fd = -1;
static pid_t child_pid = 0, status_pid = 0;
static struct termios tty_saved, tty_watch;
static bool tty_valid = false;
static volatile sig_atomic_t caught_signal = 0;
static volatile sig_atomic_t children_changed = 0;
static char **command_args;
static int command_count, substitute_index = -1;
static char *shell_name, *status_label;
static int last_status, status_finished;

struct watched {
    char *name;
    dev_t device;
    ino_t inode;
    mode_t mode;
    int descriptor;
    long entries;
};
static struct watched *watches;
static size_t watch_count, watch_capacity;
static size_t initial_file = 0, last_file = 0;

struct event_item {
    size_t index;
    uint32_t mask;
    unsigned notes;
    bool changed;
    bool replaced;
    bool directory_changed;
};
struct batch {
    struct event_item *items;
    size_t count, capacity;
};

static void message(const char *fmt, ...) {
    va_list ap;
    fprintf(stderr, "%s: ", program);
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    fputc('\n', stderr);
}

static void *allocate(size_t n) {
    void *p = malloc(n ? n : 1);
    if (!p) {
        message("malloc: %s", strerror(errno));
        exit(1);
    }
    return p;
}

static char *copy_string(const char *s) {
    char *p = allocate(strlen(s) + 1);
    strcpy(p, s);
    return p;
}

static const char *base_name(const char *s) {
    const char *p = strrchr(s, '/');
    return p ? p + 1 : s;
}

static void sleep_ms(int milliseconds) {
    struct timespec t = {milliseconds / 1000,
                         (long)(milliseconds % 1000) * 1000000};
    while (nanosleep(&t, &t) < 0 && errno == EINTR) {
        if (caught_signal) break;
    }
}

static void signal_notice(int sig) {
    if (sig == SIGCHLD) children_changed = 1;
    else if (!caught_signal) caught_signal = sig;
}

static void install_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sigemptyset(&sa.sa_mask);
    sa.sa_handler = signal_notice;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGHUP, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGQUIT, &sa, NULL);
    sigaction(SIGCHLD, &sa, NULL);
    signal(SIGPIPE, SIG_IGN);
}

static void default_handlers(void) {
    int signals[] = {SIGINT, SIGHUP, SIGTERM, SIGQUIT, SIGCHLD,
                     SIGPIPE, SIGTSTP, SIGTTIN, SIGTTOU};
    for (size_t i = 0; i < sizeof(signals)/sizeof(signals[0]); i++)
        signal(signals[i], SIG_DFL);
    sigset_t empty;
    sigemptyset(&empty);
    sigprocmask(SIG_SETMASK, &empty, NULL);
}

static void terminal_mode(bool watching) {
    if (tty_valid) tcsetattr(tty_fd, TCSANOW, watching ? &tty_watch : &tty_saved);
}

static int exit_code(int status) {
    if (WIFEXITED(status)) return WEXITSTATUS(status);
    if (WIFSIGNALED(status)) return 128 + WTERMSIG(status);
    return 0;
}

static void terminate_child(void) {
    if (child_pid <= 0 || !opt_restart) return;
    pid_t pid = child_pid;
    int st;
    if (waitpid(pid, &st, WNOHANG) == pid) {
        child_pid = 0;
        return;
    }
    kill(-pid, restart_signal);
    while (waitpid(pid, &st, 0) < 0 && errno == EINTR) {}
    child_pid = 0;
}

static void shutdown_runner(int code, bool finish_status) {
    terminate_child();
    terminal_mode(false);
    if (status_fd >= 0) {
        close(status_fd);
        status_fd = -1;
    }
    if (status_pid > 0) {
        if (!finish_status) kill(status_pid, SIGTERM);
        int status;
        while (waitpid(status_pid, &status, 0) < 0 && errno == EINTR) {}
        status_pid = 0;
    }
    if (notify_fd >= 0) close(notify_fd);
    if (tty_fd >= 0) close(tty_fd);
    fflush(stdout);
    fflush(stderr);
    exit(code);
}

static void check_signal(void) {
    if (!caught_signal) return;
    int sig = caught_signal;
    if (sig == SIGINT || sig == SIGHUP) shutdown_runner(0, false);
    terminate_child();
    terminal_mode(false);
    if (status_pid > 0) kill(status_pid, SIGTERM);
    signal(sig, SIG_DFL);
    raise(sig);
    _exit(128 + sig);
}

static void usage(bool help) {
    fputs("release: 5.7\n"
          "usage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames\n",
          stderr);
    if (!help) fputs("hint: use -h to display option summary\n", stderr);
    else fputs("summary:\n"
               "    -a  Do not consolidate events\n"
               "    -c  Clear screen before execution\n"
               "    -d  Track files added or removed from directories\n"
               "    -n  Non-interactive mode\n"
               "    -p  Wait for first event\n"
               "    -r  Run as a background process, use signal to restart\n"
               "    -s  Evaluate using a shell\n"
               "    -x  Format exit status\n"
               "    -z  Exit after the utility completes\n"
               "docs:\n"
               "    man entr\n", stdout);
    exit(1);
}

static void status_setup(void) {
    const char *path = getenv("ENTR_STATUS_SCRIPT");
    char default_path[PATH_MAX];
    if (!path || !*path) {
        struct passwd *pw = getpwuid(getuid());
        const char *home = pw ? pw->pw_dir : getenv("HOME");
        if (!home) home = ".";
        snprintf(default_path, sizeof(default_path), "%s/.entr/status.awk", home);
        path = default_path;
    }
    struct stat sb;
    if (stat(path, &sb) < 0) {
        char *parent = copy_string(path);
        char *slash = strrchr(parent, '/');
        if (slash) {
            *slash = 0;
            mkdir(*parent ? parent : "/", 0700);
        }
        free(parent);
        printf("entr: created '%s'\n", path);
        fflush(stdout);
        int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0640);
        if (fd < 0) {
            message("open: %s", strerror(errno));
            exit(1);
        }
        static const char example[] =
            "# http://eradman.com/entrproject/status-filters.html\n"
            "/^signal/ { print $3, \"terminated by signal\", $2; }\n"
            "/^exit/ { print $3, \"returned exit code\", $2; }\n";
        ssize_t written = write(fd, example, sizeof(example)-1);
        (void)written;
        close(fd);
    }
    int fds[2];
    if (pipe2(fds, O_CLOEXEC) < 0) {
        message("pipe: %s", strerror(errno));
        exit(1);
    }
    fflush(NULL);
    status_pid = fork();
    if (status_pid == 0) {
        default_handlers();
        dup2(fds[0], STDIN_FILENO);
        close(fds[0]);
        close(fds[1]);
        char *args[] = {"awk", "-F", "|", "-f", (char *)path,
                        opt_status == 1 ? "-S" : NULL, NULL};
        execvp(args[0], args);
        message("exec awk: %s", strerror(errno));
        _exit(1);
    }
    close(fds[0]);
    status_fd = fds[1];
    if (status_pid < 0) {
        message("fork: %s", strerror(errno));
        exit(1);
    }
}

static void status_report(int status) {
    if (status_fd < 0) return;
    const char *kind;
    int number;
    if (WIFEXITED(status)) {
        kind = "exit";
        number = WEXITSTATUS(status);
    } else if (WIFSIGNALED(status)) {
        kind = "signal";
        number = WTERMSIG(status);
    } else return;
    char *line;
    if (asprintf(&line, "%s|%d|%s\n", kind, number, status_label) < 0) return;
    ssize_t written = write(status_fd, line, strlen(line));
    (void)written;
    free(line);
}

static int file_stat(const char *name, struct stat *sb) {
    return follow_links ? stat(name, sb) : lstat(name, sb);
}

static long directory_entries(const char *path, bool fatal) {
    DIR *dir = opendir(path);
    if (!dir) {
        if (fatal) {
            message("unable to open directory: '%s'", path);
            shutdown_runner(1, false);
        }
        return -1;
    }
    long count = 0;
    struct dirent *entry;
    while ((entry = readdir(dir))) {
        if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) continue;
        if (entry->d_name[0] == '.' && opt_directory < 2) continue;
        count++;
    }
    closedir(dir);
    return count;
}

static uint32_t watch_mask(void) {
    uint32_t mask = IN_CLOSE_WRITE | IN_ATTRIB | IN_DELETE_SELF | IN_MOVE_SELF |
                    IN_CREATE | IN_DELETE | IN_MOVED_FROM | IN_MOVED_TO;
    if (workaround) mask |= IN_MODIFY;
    if (!follow_links) mask |= IN_DONT_FOLLOW;
    return mask;
}

static int attach_watch(struct watched *w) {
    int wd = inotify_add_watch(notify_fd, w->name, watch_mask());
    if (wd < 0) return -1;
    w->descriptor = wd;
    return 0;
}

static size_t add_watch(const char *path, const struct stat *sb) {
    for (size_t i = 0; i < watch_count; ++i) {
        if (watches[i].device == sb->st_dev && watches[i].inode == sb->st_ino)
            return i;
    }
    if (watch_count == watch_capacity) {
        watch_capacity = watch_capacity ? watch_capacity * 2 : 32;
        void *p = realloc(watches, watch_capacity * sizeof(*watches));
        if (!p) { message("realloc: %s", strerror(errno)); exit(1); }
        watches = p;
    }
    struct watched *w = &watches[watch_count];
    memset(w, 0, sizeof(*w));
    w->name = copy_string(path);
    w->device = sb->st_dev;
    w->inode = sb->st_ino;
    w->mode = sb->st_mode;
    w->descriptor = -1;
    w->entries = S_ISDIR(sb->st_mode) ? directory_entries(path, true) : 0;
    size_t index = watch_count++;
    return index;
}

static void read_watch_list(void) {
    char line[PATH_MAX];
    bool first = true;
    while (fgets(line, sizeof(line), stdin)) {
        size_t n = strlen(line);
        if (n && line[n-1] == '\n') line[--n] = 0;
        if (!n) continue;
        struct stat sb;
        if (file_stat(line, &sb) < 0) {
            message("unable to stat '%s'", line);
            continue;
        }
        if (!(S_ISREG(sb.st_mode) || S_ISDIR(sb.st_mode) || S_ISLNK(sb.st_mode))) continue;
        size_t idx = add_watch(line, &sb);
        if (first) { initial_file = last_file = idx; first = false; }
        if (opt_directory && !S_ISDIR(sb.st_mode)) {
            char *parent = copy_string(line);
            char *slash = strrchr(parent, '/');
            if (!slash) { free(parent); parent = copy_string("."); }
            else if (slash == parent) parent[1] = 0;
            else *slash = 0;
            struct stat dsb;
            if (stat(parent, &dsb) == 0 && S_ISDIR(dsb.st_mode)) add_watch(parent, &dsb);
            free(parent);
        }
    }
    if (!watch_count) {
        message("No regular files to watch");
        shutdown_runner(1, true);
    }
}

static bool input_ready(int fd) {
    struct pollfd pfd = {fd, POLLIN, 0};
    return poll(&pfd, 1, 0) > 0 && (pfd.revents & POLLIN);
}

static void batch_add(struct batch *batch, size_t index, uint32_t mask) {
    for (size_t i = 0; i < batch->count; i++) {
        if (batch->items[i].index == index) {
            batch->items[i].mask |= mask;
            return;
        }
    }
    if (batch->count == batch->capacity) {
        batch->capacity = batch->capacity ? 2*batch->capacity : 16;
        void *p = realloc(batch->items, batch->capacity * sizeof(*batch->items));
        if (!p) { message("realloc: %s", strerror(errno)); exit(1); }
        batch->items = p;
    }
    struct event_item *item = &batch->items[batch->count++];
    memset(item, 0, sizeof(*item));
    item->index = index;
    item->mask = mask;
}

static void read_events(struct batch *batch) {
    union { char data[65536]; struct inotify_event align; } buffer;
    for (;;) {
        ssize_t n = read(notify_fd, buffer.data, sizeof(buffer.data));
        if (n < 0 && errno == EINTR) continue;
        if (n <= 0) break;
        for (size_t off = 0; off < (size_t)n;) {
            struct inotify_event *ev = (void *)(buffer.data + off);
            off += sizeof(*ev) + ev->len;
            if (ev->mask & IN_Q_OVERFLOW) continue;
            for (size_t i = 0; i < watch_count; ++i) {
                if (watches[i].descriptor != ev->wd) continue;
                uint32_t mask = ev->mask & ~IN_IGNORED;
                if (mask) batch_add(batch, i, mask);
                break;
            }
        }
    }
}

static bool reopen_watch(struct watched *w, struct stat *sb) {
    int saved_error = ENOENT;
    for (int attempt = 0; attempt <= 10; attempt++) {
        if (file_stat(w->name, sb) == 0) {
            int oldwd = w->descriptor;
            if (attach_watch(w) == 0) {
                if (oldwd != w->descriptor && oldwd >= 0) inotify_rm_watch(notify_fd, oldwd);
                w->device = sb->st_dev;
                w->inode = sb->st_ino;
                return true;
            }
        }
        saved_error = errno;
        if (attempt < 10) sleep_ms(100);
        if (caught_signal) return false;
    }
    message("cannot open '%s': %s", w->name, strerror(saved_error));
    shutdown_runner(1, false);
    return false;
}

static void prepare_events(struct batch *batch) {
    for (size_t i = 0; i < batch->count; i++) {
        struct event_item *ev = &batch->items[i];
        struct watched *w = &watches[ev->index];
        uint32_t mask = ev->mask;
        if (S_ISDIR(w->mode)) {
            ev->notes = (mask & IN_ATTRIB) ? 8 : 2;
            if (mask & (IN_CREATE|IN_DELETE|IN_MOVED_FROM|IN_MOVED_TO|IN_CLOSE_WRITE|IN_MODIFY)) ev->notes |= 2;
            long entries = directory_entries(w->name, true);
            if (entries != w->entries) {
                sleep_ms(500);
                if (caught_signal) return;
                entries = directory_entries(w->name, true);
                ev->directory_changed = entries != w->entries;
                ev->changed = ev->directory_changed;
            }
            continue;
        }
        ev->notes = 0;
        if (mask & (IN_CLOSE_WRITE|IN_MODIFY)) ev->notes |= 2;
        if (mask & IN_ATTRIB) ev->notes |= 8;
        if (mask & IN_DELETE_SELF) ev->notes |= 1;
        if (mask & IN_MOVE_SELF) ev->notes |= 0x20;
        struct stat sb;
        bool exists = file_stat(w->name, &sb) == 0;
        bool replaced = !exists || sb.st_dev != w->device || sb.st_ino != w->inode ||
                        (mask & (IN_DELETE_SELF|IN_MOVE_SELF));
        if (replaced) {
            if (!reopen_watch(w, &sb)) return;
            ev->replaced = true;
            if (!(ev->notes & (1|0x20))) ev->notes |= 1;
            ev->changed = true;
        }
        if (ev->notes & 2) ev->changed = true;
        if (exists || replaced) {
            if (w->mode != sb.st_mode) ev->changed = true;
            w->mode = sb.st_mode;
        }
    }
}

static struct batch collect_events(void) {
    struct batch batch = {0};
    sleep_ms(50);
    if (caught_signal) return batch;
    read_events(&batch);
    prepare_events(&batch);
    return batch;
}

static void discard_events(void) {
    if (!input_ready(notify_fd)) return;
    struct batch batch = collect_events();
    free(batch.items);
}

static void close_extra_fds(void) {
    if (notify_fd >= 0) close(notify_fd);
    if (status_fd >= 0) close(status_fd);
    if (tty_fd > 2) close(tty_fd);
}

static void launch_child(bool force_wait) {
    if (opt_restart) terminate_child();
    check_signal();
    bool wait_now = force_wait || (!opt_restart && !opt_exit);
    if (wait_now) terminal_mode(false);
    if (opt_clear) {
        fputs(opt_clear > 1 ? "\033[2J\033[3J\033[H" : "\033[2J\033[H", stdout);
        fflush(stdout);
    }
    fflush(NULL);
    pid_t pid = fork();
    if (pid < 0) {
        message("fork: %s", strerror(errno));
        shutdown_runner(1, false);
    }
    if (pid == 0) {
        default_handlers();
        if (opt_restart) {
            setpgid(0, 0);
            int null_fd = open("/dev/null", O_RDONLY);
            if (null_fd >= 0) { dup2(null_fd, 0); if (null_fd != 0) close(null_fd); }
        } else if (tty_valid) dup2(tty_fd, STDIN_FILENO);
        close_extra_fds();
        char **args;
        char *shargs[5];
        if (opt_shell) {
            shargs[0] = shell_name;
            shargs[1] = "-c";
            shargs[2] = command_args[0];
            shargs[3] = watches[last_file].name;
            shargs[4] = NULL;
            args = shargs;
        } else {
            args = command_args;
            if (substitute_index >= 0) args[substitute_index] = watches[last_file].name;
        }
        execvp(args[0], args);
        message("exec %s: %s", args[0], strerror(errno));
        _exit(1);
    }
    child_pid = pid;
    if (opt_restart) setpgid(pid, pid);
    if (wait_now) {
        int status = 0;
        while (waitpid(pid, &status, 0) < 0 && errno == EINTR) {}
        child_pid = 0;
        last_status = exit_code(status);
        status_report(status);
        terminal_mode(true);
        check_signal();
        if (!opt_all && !force_wait) discard_events();
    }
}

static void reap_children(void) {
    children_changed = 0;
    /* Check the utility before the formatter: a short-lived formatter must not
     * replace a utility's already-available exit status. */
    if (child_pid > 0) {
        int status;
        pid_t p = waitpid(child_pid, &status, WNOHANG);
        if (p == child_pid) {
            child_pid = 0;
            last_status = exit_code(status);
            status_report(status);
            if (opt_exit) shutdown_runner(last_status, true);
        }
    }
    if (status_pid > 0) {
        int status;
        pid_t p = waitpid(status_pid, &status, WNOHANG);
        if (p == status_pid) {
            status_pid = 0;
            status_finished = 1;
            message("status process terminated");
            shutdown_runner(0, false);
        }
    }
    /* An asynchronous invocation may supersede a prior -z invocation. */
    int status;
    while (waitpid(-1, &status, WNOHANG) > 0) {}
}

static void watch_loop(void) {
    if (!opt_postpone) launch_child(false);
    for (;;) {
        check_signal();
        reap_children();
        struct pollfd fds[2];
        fds[0] = (struct pollfd){notify_fd, POLLIN, 0};
        nfds_t n = 1;
        if (tty_valid) fds[n++] = (struct pollfd){tty_fd, POLLIN, 0};
        int result = poll(fds, n, -1);
        if (result < 0) { if (errno == EINTR) continue; message("poll: %s", strerror(errno)); shutdown_runner(1, false); }
        check_signal();
        if (children_changed) { reap_children(); check_signal(); }
        bool keyboard = false;
        if (n > 1 && (fds[1].revents & POLLIN)) {
            unsigned char input[64];
            ssize_t count = read(tty_fd, input, sizeof(input));
            if (count <= 0) shutdown_runner(0, false);
            for (ssize_t i = 0; i < count; i++) {
                if (input[i] == 'q') shutdown_runner(0, false);
                if (input[i] == ' ') keyboard = true;
            }
        }
        bool changed = false, directory_changed = false, replaced = false;
        if (fds[0].revents & POLLIN) {
            struct batch batch = collect_events();
            check_signal();
            for (size_t i = 0; i < batch.count; ++i)
                if (batch.items[i].directory_changed) directory_changed = true;
            if (directory_changed && opt_restart) {
                free(batch.items);
                message("directory altered");
                shutdown_runner(2, false);
            }
            for (size_t i = 0; i < batch.count; ++i) {
                struct event_item *ev = &batch.items[i];
                struct watched *w = &watches[ev->index];
                bool isdir = S_ISDIR(w->mode);
                if (trace_events && ((!isdir && S_ISREG(w->mode)) || ev->directory_changed))
                    fprintf(stderr, "%zu/%zu: fflags: 0x%x %c %o %s\n",
                            i, batch.count, ev->notes, isdir ? 'd' : 'r',
                            (unsigned)w->mode, w->name);
                if (ev->changed) {
                    if (!changed && !isdir) last_file = ev->index;
                    if (!isdir) changed = true;
                }
                if (ev->replaced) replaced = true;
            }
            free(batch.items);
        }
        if (replaced) { sleep_ms(50); check_signal(); }
        if (directory_changed) {
            launch_child(true);
            message("directory altered");
            shutdown_runner(2, true);
        }
        if (keyboard || changed) launch_child(false);
    }
}

int main(int argc, char **argv) {
    program = base_name(argv[0]);
    if (argc > 1 && !strcmp(argv[1], "-h")) usage(true);
    int option;
    while ((option = getopt(argc, argv, "+acdnprsxz")) != -1) {
        switch (option) {
            case 'a': opt_all = 1; break;
            case 'c': opt_clear++; break;
            case 'd': opt_directory++; break;
            case 'n': opt_noninteractive = 1; break;
            case 'p': opt_postpone = 1; break;
            case 'r': opt_restart = 1; break;
            case 's': opt_shell = 1; break;
            case 'x': opt_status++; break;
            case 'z': opt_exit = 1; break;
            default: usage(false);
        }
    }
    if (optind >= argc || isatty(STDIN_FILENO)) usage(false);
    if (opt_restart && opt_status) { message("-r and -x may not be combined"); return 1; }
    command_args = argv + optind;
    command_count = argc - optind;
    if (opt_shell && command_count != 1) {
        message("-s requires commands to be formatted as a single argument");
        return 1;
    }
    const char *sig = getenv("ENTR_RESTART_SIGNAL");
    if (sig) {
        if (!strncmp(sig, "SIG", 3)) sig += 3;
        if (!strcmp(sig, "HUP")) restart_signal = SIGHUP;
        else if (!strcmp(sig, "INT")) restart_signal = SIGINT;
        else if (!strcmp(sig, "QUIT")) restart_signal = SIGQUIT;
        else {
            message("unrecognized signal: %s <> (HUP, INT, QUIT, TERM, USR1, USR2)", sig);
            return 1;
        }
    }
    setenv("PAGER", "cat", 0);
    shell_name = getenv("SHELL");
    if (!shell_name) shell_name = "/bin/sh";
    status_label = copy_string(base_name(opt_shell ? shell_name : command_args[0]));
    if (!opt_shell) for (int i = 0; i < command_count; i++) {
        if (!strcmp(command_args[i], "/_")) { substitute_index = i; break; }
    }
    trace_events = getenv("EV_TRACE") != NULL;
    follow_links = getenv("ENTR_FOLLOW_SYMLINK") != NULL;
    workaround = getenv("ENTR_INOTIFY_WORKAROUND") != NULL;
