            message("unable to get terminal attributes, use '-n' to run non-interactively");
            shutdown_runner(1, false);
        }
        tty_valid = true;
        tty_watch = tty_saved;
        tty_watch.c_lflag &= ~(ICANON | ECHO);
        tty_watch.c_cc[VMIN] = 1;
        tty_watch.c_cc[VTIME] = 0;
        terminal_mode(true);
    }
    watch_loop();
    return 0;
}
